from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_public(path: str) -> str:
    """Return the text of the file `path` inside the directory `notes`.

    `notes` is relative to the current working directory. `path` comes from
    an untrusted request. A path that wanders but stays inside `notes`
    (e.g. "sub/../a.txt") is allowed. Any path that leaves `notes` (e.g.
    "..", an absolute path, "sub/../../x", or a symlink pointing outside)
    reads nothing. A missing, unreadable, non-text or non-file target, or an
    invalid name (e.g. containing a NUL byte), yields "".
    """
    try:
        if "\x00" in path:
            return ""
        requested = Path(path)
        if requested.is_absolute() or requested.anchor:
            return ""
        base = Path(NOTES_DIR).resolve()
        target = (base / requested).resolve()
        if not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("secret", encoding="utf-8")
    (tmp_path / "x").write_text("secret-x", encoding="utf-8")
    sibling = tmp_path / "notes2"
    sibling.mkdir()
    (sibling / "c.txt").write_text("sibling", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_plain_file(root: Path) -> None:
    assert read_public("a.txt") == "hello"


def test_reads_nested_file(root: Path) -> None:
    assert read_public("sub/b.txt") == "nested"


def test_wandering_inside_is_fine(root: Path) -> None:
    assert read_public("sub/../a.txt") == "hello"
    assert read_public("./sub/./b.txt") == "nested"


def test_missing_file(root: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""


def test_directory_and_empty(root: Path) -> None:
    assert read_public("sub") == ""
    assert read_public("") == ""
    assert read_public(".") == ""


def test_parent_escape(root: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../x") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("../notes/../secret.txt") == ""


def test_sibling_with_shared_prefix(root: Path) -> None:
    assert read_public("../notes2/c.txt") == ""


def test_absolute_paths(root: Path) -> None:
    assert read_public(str(root / "secret.txt")) == ""
    assert read_public(str(root / NOTES_DIR / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""


def test_symlink_escape(root: Path) -> None:
    link = root / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(root / "secret.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_public("link.txt") == ""


def test_symlinked_dir_escape(root: Path) -> None:
    link = root / NOTES_DIR / "outside"
    try:
        link.symlink_to(root, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_public("outside/secret.txt") == ""


def test_symlink_inside_is_ok(root: Path) -> None:
    link = root / NOTES_DIR / "alias.txt"
    try:
        link.symlink_to(root / NOTES_DIR / "a.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_public("alias.txt") == "hello"


def test_nul_byte(root: Path) -> None:
    assert read_public("a.txt\x00../secret.txt") == ""
    assert read_public("\x00") == ""


def test_undecodable_file(root: Path) -> None:
    (root / NOTES_DIR / "bin.dat").write_bytes(b"\xff\xfe\x80")
    assert read_public("bin.dat") == ""


def test_unreadable_notes_dir_missing(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_public("a.txt") == ""
